public class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    // Running totals tracked across batches
    public Integer recordsUpdated = 0;
    public Integer recordsFailed = 0;
    public Decimal overdueAmount = 0.0;

    public OverdueInvoiceBatch() {
        // No-argument constructor
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Status__c, Due_Date__c, Amount__c, Customer_Email__c 
            FROM FB_Invoice__c 
            WHERE Status__c = 'Open' AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> scope) {
        List<FB_Invoice__c> invoicesToUpdate = new List<FB_Invoice__c>();
        for (FB_Invoice__c inv : scope) {
            inv.Status__c = 'Overdue';
            invoicesToUpdate.add(inv);
        }

        if (!invoicesToUpdate.isEmpty()) {
            Database.SaveResult[] results = Database.update(invoicesToUpdate, false);
            for (Integer i = 0; i < results.size(); i++) {
                Database.SaveResult sr = results[i];
                FB_Invoice__c inv = invoicesToUpdate[i];
                if (sr.isSuccess()) {
                    this.recordsUpdated++;
                    if (inv.Amount__c != null) {
                        this.overdueAmount += inv.Amount__c;
                    }
                } else {
                    this.recordsFailed++;
                }
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = this.recordsUpdated,
            Records_Failed__c = this.recordsFailed,
            Overdue_Amount__c = this.overdueAmount
        );
        insert summary;
    }
}
