public with sharing class ContactDomainService {

    /**
     * Groups contacts of the given accounts by the domain part of their email address (lower-cased).
     * Contacts without an email address are ignored.
     * Respects the running user's sharing.
     *
     * @param accountIds A set of Account IDs to filter contacts by.
     * @return A Map where the key is the lower-case email domain and the value is a List of Contacts.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> domainToContacts = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return domainToContacts;
        }

        // Query contacts with AccountId, Email, and Id, filtering by the provided accountIds
        // and ensuring Email is not null. With sharing is enforced by the class declaration.
        List<Contact> contacts = [
            SELECT Id, Email, AccountId 
            FROM Contact 
            WHERE AccountId IN :accountIds 
              AND Email != NULL
        ];

        for (Contact con : contacts) {
            String email = con.Email;
            // Extract the domain part after the '@' character
            Integer atIndex = email.indexOf('@');
            if (atIndex != -1 && atIndex < email.length() - 1) {
                String domain = email.substring(atIndex + 1).toLowerCase();

                if (!domainToContacts.containsKey(domain)) {
                    domainToContacts.put(domain, new List<Contact>());
                }
                domainToContacts.get(domain).add(con);
            }
        }

        return domainToContacts;
    }
}
