public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        // 1. Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // 2. Validate object existence and accessibility
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name cannot be blank.');
        }

        SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName);
        if (sObjectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('The running user does not have read access to object: ' + objectApiName);
        }

        Map<String, SObjectField> fieldsMap = objectDescribe.fields.getMap();

        // Use a Set to track all fields that must be checked for read permission
        Set<String> fieldsToValidate = new Set<String>();

        // 3. Validate requested SELECT fields
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty.');
        }

        Set<String> cleanSelectFields = new Set<String>{'id'}; // 'Id' is always included and queried
        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field name cannot be blank.');
            }
            SObjectField fld = fieldsMap.get(fieldName.toLowerCase());
            if (fld == null) {
                throw new SearchException('Field does not exist: ' + fieldName);
            }
            fieldsToValidate.add(fld.getDescribe().getName());
            cleanSelectFields.add(fld.getDescribe().getName());
        }

        // 4. Validate filter keys and filterability
        Map<String, Object> validFilters = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field key cannot be blank.');
                }
                SObjectField fld = fieldsMap.get(filterKey.toLowerCase());
                if (fld == null) {
                    throw new SearchException('Filter field does not exist: ' + filterKey);
                }
                DescribeFieldResult fldDescribe = fld.getDescribe();
                if (!fldDescribe.isFilterable()) {
                    throw new SearchException('Field is not filterable: ' + filterKey);
                }
                fieldsToValidate.add(fldDescribe.getName());
                validFilters.put(fldDescribe.getName(), filters.get(filterKey));
            }
        }

        // 5. Validate ORDER BY field and sortability
        String cleanOrderByField = null;
        if (String.isNotBlank(orderByField)) {
            SObjectField fld = fieldsMap.get(orderByField.trim().toLowerCase());
            if (fld == null) {
                throw new SearchException('Order by field does not exist: ' + orderByField);
            }
            DescribeFieldResult fldDescribe = fld.getDescribe();
            if (!fldDescribe.isSortable()) {
                throw new SearchException('Field is not sortable: ' + orderByField);
            }
            fieldsToValidate.add(fldDescribe.getName());
            cleanOrderByField = fldDescribe.getName();
        }

        // 6. Enforce Field-Level Security (FLS) read permission on all involved fields
        for (String validatedField : fieldsToValidate) {
            SObjectField fld = fieldsMap.get(validatedField.toLowerCase());
            if (fld != null && !fld.getDescribe().isAccessible()) {
                throw new SearchException('The running user does not have read access to field: ' + validatedField);
            }
        }

        // 7. Construct dynamic SOQL query
        String selectClause = 'SELECT ' + String.join(new List<String>(cleanSelectFields), ', ');
        String fromClause = ' FROM ' + objectDescribe.getName();

        String whereClause = '';
        Map<String, Object> queryBindMap = new Map<String, Object>();
        if (!validFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            Integer bindCounter = 0;
            for (String filterField : validFilters.keySet()) {
                Object val = validFilters.get(filterField);
                String bindVarName = 'filterBindValue' + bindCounter;
                queryBindMap.put(bindVarName, val);

                if (val == null) {
                    conditions.add(filterField + ' = null');
                } else {
                    conditions.add(filterField + ' = :' + bindVarName);
                }
                bindCounter++;
            }
            whereClause = ' WHERE ' + String.join(conditions, ' AND ');
        }

        String orderByClause = '';
        if (cleanOrderByField != null) {
            orderByClause = ' ORDER BY ' + cleanOrderByField + ' ASC';
        }

        String limitClause = ' LIMIT :maxRows';

        String queryStr = selectClause + fromClause + whereClause + orderByClause + limitClause;

        // 8. Execute query with binding and sharing rules enforced via 'with sharing' context
        try {
            queryBindMap.put('maxRows', maxRows);
            return Database.queryWithBinds(queryStr, queryBindMap, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('An unexpected error occurred during search: ' + e.getMessage(), e);
        }
    }
}
