public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='The email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID' description='The ID of the contact if found')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a contact was found, false otherwise')
        public Boolean found;

        public Result(Id contactId, Boolean found) {
            this.contactId = contactId;
            this.found = found;
        }
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email. If multiple are found, returns the oldest one.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Clean and collect unique emails from requests
        Set<String> cleanEmails = new Set<String>();
        List<String> processedRequestEmails = new List<String>();

        for (Request req : requests) {
            String cleanEmail = null;
            if (req.email != null) {
                cleanEmail = req.email.trim();
                if (String.isNotBlank(cleanEmail)) {
                    cleanEmails.add(cleanEmail.toLowerCase());
                } else {
                    cleanEmail = null;
                }
            }
            processedRequestEmails.add(cleanEmail);
        }

        // Query matching contacts ordered by CreatedDate ascending to get the earliest contact first
        Map<String, Contact> emailToOldestContactMap = new Map<String, Contact>();
        if (!cleanEmails.isEmpty()) {
            for (Contact con : [
                SELECT Id, Email 
                FROM Contact 
                WHERE Email IN :cleanEmails 
                WITH USER_MODE
                ORDER BY CreatedDate ASC
            ]) {
                if (con.Email != null) {
                    String lowerEmail = con.Email.toLowerCase();
                    // Since we order by CreatedDate ASC, the first record we map is the oldest.
                    // We only put it if it is not already in the map.
                    if (!emailToOldestContactMap.containsKey(lowerEmail)) {
                        emailToOldestContactMap.put(lowerEmail, con);
                    }
                }
            }
        }

        // Build results in the same order as requests
        for (String email : processedRequestEmails) {
            if (email == null) {
                results.add(new Result(null, false));
            } else {
                Contact matchingContact = emailToOldestContactMap.get(email.toLowerCase());
                if (matchingContact != null) {
                    results.add(new Result(matchingContact.Id, true));
                } else {
                    results.add(new Result(null, false));
                }
            }
        }

        return results;
    }
}
