public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body cannot be null or blank.');
        }

        Map<String, Object> jsonMap;
        try {
            Object parsedObj = JSON.deserializeUntyped(body);
            if (!(parsedObj instanceof Map<String, Object>)) {
                throw new PayloadException('Payload is not a JSON object.');
            }
            jsonMap = (Map<String, Object>) parsedObj;
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON format: ' + e.getMessage());
        }

        Order order = new Order();

        // Parse order number
        String rawNumber = (String) jsonMap.get('number');
        if (String.isBlank(rawNumber)) {
            throw new PayloadException('Order number is missing or blank.');
        }
        order.orderNumber = rawNumber;

        // Parse date
        String rawDate = (String) jsonMap.get('date');
        if (String.isNotBlank(rawDate)) {
            try {
                order.orderDate = Date.valueOf(rawDate);
            } catch (Exception e) {
                throw new PayloadException('Invalid date format. Expected yyyy-MM-dd.');
            }
        }

        // Parse currency code
        order.currencyCode = (String) jsonMap.get('currency');

        // Parse customer
        if (jsonMap.containsKey('customer') && jsonMap.get('customer') != null) {
            Object customerObj = jsonMap.get('customer');
            if (customerObj instanceof Map<String, Object>) {
                Map<String, Object> customerMap = (Map<String, Object>) customerObj;
                order.customerEmail = (String) customerMap.get('email');
            }
        }

        // Parse lines
        order.lines = new List<Line>();
        order.total = 0.00;

        if (jsonMap.containsKey('lines') && jsonMap.get('lines') != null) {
            Object linesObj = jsonMap.get('lines');
            if (linesObj instanceof List<Object>) {
                List<Object> linesList = (List<Object>) linesObj;
                for (Object item : linesList) {
                    if (item instanceof Map<String, Object>) {
                        Map<String, Object> lineMap = (Map<String, Object>) item;
                        Line line = parseLine(lineMap);
                        order.lines.add(line);
                        order.total += line.lineTotal;
                    }
                }
            }
        }

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // SKU validation
        String sku = (String) lineMap.get('sku');
        if (String.isBlank(sku)) {
            throw new PayloadException('Line SKU is missing or blank.');
        }
        line.sku = sku;

        // Quantity validation
        Object rawQty = lineMap.get('quantity');
        if (rawQty == null) {
            throw new PayloadException('Line quantity is missing.');
        }
        Integer quantity;
        try {
            quantity = Integer.valueOf(rawQty);
        } catch (Exception e) {
            throw new PayloadException('Line quantity must be an integer.');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        line.quantity = quantity;

        // Unit Price validation
        Object rawPrice = lineMap.get('unitPrice');
        if (rawPrice == null) {
            throw new PayloadException('Line unit price is missing.');
        }
        Decimal unitPrice;
        try {
            unitPrice = Decimal.valueOf(String.valueOf(rawPrice));
        } catch (Exception e) {
            throw new PayloadException('Line unit price must be a valid number.');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line unit price must be non-negative.');
        }
        line.unitPrice = unitPrice;

        // Discount validation & logic
        Decimal discount = 0;
        Object rawDiscount = lineMap.get('discount');
        if (rawDiscount != null) {
            try {
                discount = Decimal.valueOf(String.valueOf(rawDiscount));
            } catch (Exception e) {
                throw new PayloadException('Line discount must be a valid number.');
            }
        }
        line.discount = discount;

        // Calculate Line Total
        Decimal calculatedLineTotal = Decimal.valueOf(quantity) * unitPrice * (1.0 - discount);
        line.lineTotal = calculatedLineTotal.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ackMap = new Map<String, Object>();
        ackMap.put('number', order.orderNumber);
        ackMap.put('status', 'RECEIVED');
        ackMap.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ackMap.put('total', order.total);
        return JSON.serialize(ackMap);
    }
}
