public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new LeadImportService.ImportResult();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        // Maps the index in leadsToInsert back to the original index in leads
        Map<Integer, Integer> insertIndexToOriginalIndex = new Map<Integer, Integer>();
        Set<String> processedEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead originalLead = leads[i];
            if (originalLead == null) {
                result.errorsByIndex.put(i, 'Lead record is null');
                continue;
            }

            // Set LeadSource to 'Web' if it is blank
            if (String.isBlank(originalLead.LeadSource)) {
                originalLead.LeadSource = 'Web';
            }

            // Check for duplicate emails within the import batch
            if (String.isNotBlank(originalLead.Email)) {
                String normalizedEmail = originalLead.Email.trim().toLowerCase();
                if (processedEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                } else {
                    processedEmails.add(normalizedEmail);
                }
            }

            // Prepare for database insertion
            insertIndexToOriginalIndex.put(leadsToInsert.size(), i);
            leadsToInsert.add(originalLead);
        }

        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer originalIndex = insertIndexToOriginalIndex.get(j);

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    List<String> errorMessages = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        errorMessages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(errorMessages, '; '));
                }
            }
        }

        return result;
    }
}
