            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank.');
        }

        // Retrieve SObjectType safely (case-insensitive check via Schema.getGlobalDescribe)
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjectType = globalDescribe.get(objectApiName.toLowerCase());
        if (sObjectType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Retrieve SObjectField safely (case-insensitive check via fields map)
        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldsMap = objectDescribe.fields.getMap();
        Schema.SObjectField sObjectField = fieldsMap.get(fieldApiName.toLowerCase());
        if (sObjectField == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        // Verify that the field is a picklist or multi-select picklist
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        List<Schema.PicklistEntry> picklistValues = fieldDescribe.getPicklistValues();

        if (picklistValues != null) {
            for (Schema.PicklistEntry entry : picklistValues) {
                if (entry.isActive()) {
                    options.add(new PicklistService.Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    ));
                }
            }
        }

        return options;
    }
}
