    public void execute(QueueableContext context) {
        // Attach the transaction finalizer before doing any work
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        if (this.accountIds == null || this.accountIds.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : this.accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                Description = 'Synced to ERP'
            ));
        }

        // Perform an all-or-nothing update. If it fails, an exception is thrown,
        // causing the job to fail and rollback the transaction.
        update accountsToUpdate;
    }
