public with sharing class OpportunityPipelineHandler {
    // Recursion guard to prevent infinite loops between Account update and Opportunity update
    private static Boolean isRunning = false;

    public static void handleAfterInsert(List<Opportunity> newOpps) {
        if (isRunning) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void handleAfterUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldOppsMap) {
        if (isRunning) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newOpp : newOpps) {
            Opportunity oldOpp = oldOppsMap.get(newOpp.Id);

            // Check if any fields affecting our roll-ups have changed, or if the Account changed
            Boolean accountChanged = (newOpp.AccountId != oldOpp.AccountId);
            Boolean amountChanged = (newOpp.Amount != oldOpp.Amount);
            Boolean statusChanged = (newOpp.IsClosed != oldOpp.IsClosed);

            if (accountChanged || amountChanged || statusChanged) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
                if (oldOpp.AccountId != null && accountChanged) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        updateAccounts(accountIds);
    }

    public static void handleAfterDelete(List<Opportunity> oldOpps) {
        if (isRunning) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void handleAfterUndelete(List<Opportunity> newOpps) {
        if (isRunning) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    private static void updateAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        isRunning = true;
        try {
            // Initialize all affected accounts with default values (0 and 0)
            Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.put(accId, new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = 0.00,
                    FB_Open_Opportunities__c = 0
                ));
            }

            // Aggregate open opportunities for the specified accounts
            List<AggregateResult> results = [
                SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) totalCount
                FROM Opportunity
                WHERE AccountId IN :accountIds AND IsClosed = false
                GROUP BY AccountId
            ];

            for (AggregateResult ar : results) {
                Id accId = (Id) ar.get('AccountId');
                Decimal sumAmount = (Decimal) ar.get('totalAmount');
                Integer countOpp = (Integer) ar.get('totalCount');

                Account acc = accountsToUpdate.get(accId);
                if (acc != null) {
                    acc.FB_Open_Pipeline__c = (sumAmount != null) ? sumAmount : 0.00;
                    acc.FB_Open_Opportunities__c = (countOpp != null) ? countOpp : 0;
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate.values();
            }
        } finally {
            isRunning = false;
        }
    }
}
