public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    // No-argument constructor
    public LogPurgeJob() {}

    /**
     * Schedulable execute method.
     * Delegates the deletion to a batch job to safely handle large volumes of logs
     * without hitting governor limits.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(this, 200);
    }

    /**
     * Batchable start method.
     * Queries for log records that match the retention criteria:
     * - Created more than 30 days ago and Level__c is NOT 'ERROR' (or is blank/null)
     * - Created more than 180 days ago and Level__c is 'ERROR'
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = NULL))
               OR (CreatedDate < :oneEightyDaysAgo AND Level__c = 'ERROR')
        ]);
    }

    /**
     * Batchable execute method.
     * Deletes the scoped batch of log records.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (scope != null && !scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    /**
     * Batchable finish method.
     */
    public void finish(Database.BatchableContext bc) {
        // No post-processing required
    }

    /**
     * Schedules the job to run nightly at 02:00 AM.
     * Job Name: "Log purge (nightly)"
     * Cron Expression: "0 0 2 * * ?" (Seconds, Minutes, Hours, Day_of_month, Month, Day_of_week)
     * 
     * @return Id of the scheduled CronTrigger job.
     */
    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        String cronExpression = '0 0 2 * * ?';
        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }
}
