public with sharing class OpportunityRollupService {

    /**
     * Calculates the sum of closed-won Opportunity Amounts for the current calendar year
     * for a given set of Account IDs.
     * 
     * @param accountIds The set of Account IDs to retrieve the won amounts for.
     * @return A map where every requested Account ID is mapped to its sum of won amounts (or 0 if none).
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Initialize the map with 0 for all requested accounts to guarantee they exist in the result.
        for (Id accId : accountIds) {
            if (accId != null) {
                result.put(accId, 0.00);
            }
        }

        // Compute current calendar year boundaries.
        Integer currentYear = System.Today().year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date endOfYear = Date.newInstance(currentYear, 12, 31);

        // Single aggregate query to calculate sums in the database.
        List<AggregateResult> groupedResults = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :result.keySet()
              AND IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate <= :endOfYear
            GROUP BY AccountId
        ];

        // Populate the results map with the calculated sums.
        for (AggregateResult ar : groupedResults) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');

            // If the SUM is null (i.e., all qualifying opportunities have blank Amounts), default to 0.
            if (totalAmount == null) {
                totalAmount = 0.00;
            }
            result.put(accountId, totalAmount);
        }

        return result;
    }
}
