public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingOppIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.StageName == 'Closed Won') {
                qualifyingOppIds.add(opp.Id);
            }
        }
        triggerFulfilmentService(qualifyingOppIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingOppIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingOppIds.add(opp.Id);
            }
        }
        triggerFulfilmentService(qualifyingOppIds);
    }

    private void triggerFulfilmentService(Set<Id> oppIds) {
        if (oppIds != null && !oppIds.isEmpty()) {
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(oppIds);
        }
    }
