    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            if (existingRecords != null && existingRecords.containsKey(opp.Id)) {
                Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
                if (oldOpp.StageName == 'Closed Won') {
                    if (opp.Amount != oldOpp.Amount) {
                        this.error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                    }
                }
            }
        }
    }
}
