            return new List<Opportunity>();
        }

        fflib_QueryFactory qf = newQueryFactory();

        // Add parent Account Name
        qf.selectField('Account.Name');

        // Filter for open opportunities belonging to the given Account IDs
        qf.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Order by: highest Amount first, nulls last, then earliest CloseDate first
        qf.addOrdering('Amount', fflib_QueryFactory.SortOrder.DESCENDING, true);
        qf.addOrdering('CloseDate', fflib_QueryFactory.SortOrder.ASCENDING);

        // Limit the number of records returned
        qf.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(qf.toSOQL());
    }
