public with sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason cannot be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        List<Case> casesToUpdate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            casesToUpdate.add(c);

            Task t = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            tasksToCreate.add(t);
        }

        if (!casesToUpdate.isEmpty()) {
            fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
            for (Case c : casesToUpdate) {
                uow.registerDirty(c);
            }
            for (Task t : tasksToCreate) {
                uow.registerNew(t);
            }
            uow.commitWork();
        }
    }
}
