            Deal_Won__e event = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            uow.registerPublishAfterSuccess(event);
        }

        uow.commitWork();

        return oppsToUpdate.size();
    }
