    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer totalClosed = 0;

        // Use a SOQL for loop with record chunks to keep the memory footprint low.
        // We filter for IsClosed = false and CloseDate < cutoff.
        for (List<Opportunity> chunk : [
            SELECT Id, StageName 
            FROM Opportunity 
            WHERE IsClosed = false 
            AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            update chunk;
            totalClosed += chunk.size();
        }

        return totalClosed;
    }
}
