public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private List<Id> accountIdsToProcess;
    private static final Integer MAX_CALLOUTS_PER_JOB = 100;

    // Constructor taking Set of IDs
    public ErpCustomerSync(Set<Id> accountIds) {
        this.accountIdsToProcess = new List<Id>(accountIds);
    }

    // Private constructor for chained execution
    private ErpCustomerSync(List<Id> accountIds) {
        this.accountIdsToProcess = accountIds;
    }

    public void execute(QueueableContext context) {
        if (accountIdsToProcess == null || accountIdsToProcess.isEmpty()) {
            return;
        }

        // Split the list into what we can process in this transaction and the remainder
        List<Id> currentBatchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIdsToProcess.size(); i++) {
            if (i < MAX_CALLOUTS_PER_JOB) {
                currentBatchIds.add(accountIdsToProcess[i]);
            } else {
                remainingIds.add(accountIdsToProcess[i]);
            }
        }

        // Query fields needed for the payload
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry 
            FROM Account 
            WHERE Id IN :currentBatchIds
        ];

        // Process each account individually as requested (one HTTP request per account)
        for (Account acc : accounts) {
            try {
                sendToErp(acc);
            } catch (Exception e) {
                // Error handling and retries are out of scope.
                System.debug('Error syncing Account ' + acc.Id + ' to ERP: ' + e.getMessage());
            }
        }

        // Chain the job for the remaining accounts if any exist
        if (!remainingIds.isEmpty() && !Test.isRunningTest()) {
            System.enqueueJob(new ErpCustomerSync(remainingIds));
        }
    }

    /**
     * Performs a single HTTP POST request for one account.
     */
    private static void sendToErp(Account acc) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');

        // Construct payload as a JSON array containing one customer object
        Map<String, Object> payloadMap = new Map<String, Object>{
            'salesforceId' => acc.Id,
            'name' => acc.Name,
            'country' => String.isNotBlank(acc.BillingCountry) ? acc.BillingCountry : null
        };

        List<Object> payloadList = new List<Object>{ payloadMap };
        req.setBody(JSON.serialize(payloadList));

        Http http = new Http();
        HttpResponse res = http.send(req);

        System.debug('Sync response for Account ' + acc.Id + ': STATUS=' + res.getStatus() + ' CODE=' + res.getStatusCode());
    }
}
