    /**
     * Publishes a Deal_Stage_Change__e platform event for each opportunity in the input list.
     * Note: Per the requirements, EventBus.publish is called individually inside the loop.
     * While this maps SaveResults 1:1, calling publish individually in a loop is subject to the 
     * 150 DML/publish statements limit per transaction. If bulk-safe execution for >150 records 
     * is required, a single EventBus.publish(List<SObject>) call should be used instead.
     * 
     * @param opportunities The list of Opportunity records to publish events for.
     * @return A list of Database.SaveResult matching the order of the input opportunities.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e event = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            );

            // Publish each event individually per requirements
            Database.SaveResult result = EventBus.publish(event);
            results.add(result);
        }

        return results;
    }
}
