public with sharing class FollowUpTaskService {

    /**
     * Creates follow-up tasks for the specified opportunities.
     * Uses bulk DML with partial success to handle validation failures gracefully
     * without hitting the 150 DML governor limit.
     * 
     * @param opportunityIds List of Opportunity IDs to process
     * @return Set<Id> List of Opportunity IDs for which task creation failed
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Fetch Opportunity details needed for Task creation
        Map<Id, Opportunity> opportunitiesMap = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId 
            FROM Opportunity 
            WHERE Id IN :opportunityIds
        ]);

        List<Task> tasksToCreate = new List<Task>();
        // Keep track of the mapping between the Task list index and the Opportunity ID
        List<Id> taskIndexToOppIdMap = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = opportunitiesMap.get(oppId);
            if (opp != null) {
                Task followUpTask = new Task(
                    WhatId = opp.Id,
                    OwnerId = opp.OwnerId,
                    Subject = 'Follow up: ' + opp.Name,
                    ActivityDate = System.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                );
                tasksToCreate.add(followUpTask);
                taskIndexToOppIdMap.add(opp.Id);
            } else {
                // If the opportunity doesn't exist, we count it as a failure to create a task
                failedOpportunityIds.add(oppId);
            }
        }

        if (!tasksToCreate.isEmpty()) {
            // Bulk insert with allOrNone set to false to allow partial success
            Database.SaveResult[] saveResults = Database.insert(tasksToCreate, false);

            for (Integer i = 0; i < saveResults.size(); i++) {
                Database.SaveResult sr = saveResults[i];
                if (!sr.isSuccess()) {
                    // Match the failed DML index back to the Opportunity ID
                    Id failedOppId = taskIndexToOppIdMap[i];
                    failedOpportunityIds.add(failedOppId);
                }
            }
        }

        return failedOpportunityIds;
    }
}
```

