public with sharing class AccountRatingService {

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Fetch accounts and their open opportunities
        List<Account> accountsToUpdate = [
            SELECT Id, Rating, 
                   (SELECT Amount FROM Opportunities WHERE IsClosed = false) 
            FROM Account 
            WHERE Id IN :accountIds
        ];

        List<Account> updatedAccounts = new List<Account>();

        for (Account acc : accountsToUpdate) {
            String newRating = 'Cold'; // Default if there are no open opportunities

            if (!acc.Opportunities.isEmpty()) {
                newRating = 'Warm'; // Default if open opportunities exist but none are >= 100k
                for (Opportunity opp : acc.Opportunities) {
                    if (opp.Amount >= 100000) {
                        newRating = 'Hot';
                        break; // Hot is the highest tier, no need to keep checking
                    }
                }
            }

            // Only update if the rating has actually changed to save DML statements
            if (acc.Rating != newRating) {
                acc.Rating = newRating;
                updatedAccounts.add(acc);
            }
        }

        if (!updatedAccounts.isEmpty()) {
            update updatedAccounts;
        }
    }
}
