    /**
     * Applies standard discounts to OpportunityLineItems where Discount is null.
     * Uses PricingRules.standardDiscountForFamily to avoid SOQL governor limits.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lineItems) {
        List<OpportunityLineItem> itemsToProcess = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();

        // 1. Filter for items without a discount and collect their Product2Ids
        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null && line.Product2Id != null) {
                itemsToProcess.add(line);
                productIds.add(line.Product2Id);
            }
        }

        if (itemsToProcess.isEmpty()) {
            return;
        }

        // 2. Bulk query Product2 Families in a single query to avoid SOQL-in-loop limits
        Map<Id, Product2> products = new Map<Id, Product2>([
            SELECT Family 
            FROM Product2 
            WHERE Id IN :productIds
        ]);

        // 3. Apply the discount using the centralized PricingRules logic
        for (OpportunityLineItem line : itemsToProcess) {
            Product2 prod = products.get(line.Product2Id);
            String family = (prod != null) ? prod.Family : null;

            // Call the family-based rule to keep pricing logic encapsulated without querying
            line.Discount = PricingRules.standardDiscountForFamily(family);
        }
