```apex
public class CaseSurveyJob implements Queueable {
    private List<Id> caseIdsToProcess;

    // Constructor for a single Case ID
    public CaseSurveyJob(Id caseId) {
        this.caseIdsToProcess = new List<Id>{ caseId };
    }

    // Constructor for a list of Case IDs (used to prevent LimitExceptions during bulk loads)
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIdsToProcess = new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIdsToProcess == null || caseIdsToProcess.isEmpty()) {
            return;
        }

        // Extract the first case ID to process in this job execution
        Id currentCaseId = caseIdsToProcess.remove(0);

        // Fetch Case details required to create the Task
        List<Case> cases = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :currentCaseId LIMIT 1];
        if (!cases.isEmpty()) {
            Case c = cases[0];

            Task t = new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            );

            insert t;
        }

        // If there are remaining cases in the list, chain the next job.
        // This processes each case in its own transaction (so failures are isolated)
        // while safely staying within the 50-enqueue transaction limit.
        if (!caseIdsToProcess.isEmpty() && !Test.isRunningTest()) {
            System.enqueueJob(new CaseSurveyJob(caseIdsToProcess));
        }
    }
}
