public with sharing class AccountCountrySync {

    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountsMap) {
        // Step 1: Identify which accounts had their BillingCountry changed, 
        // and map their Id to a list of old and new BillingCountry values.
        Map<Id, BillingCountryChange> updatedAccountsMap = new Map<Id, BillingCountryChange>();

        for (Account newAcc : newAccounts) {
            Account oldAcc = oldAccountsMap.get(newAcc.Id);

            // Check if BillingCountry has changed (handling null transitions safely)
            if (newAcc.BillingCountry != oldAcc.BillingCountry) {
                updatedAccountsMap.put(newAcc.Id, new BillingCountryChange(oldAcc.BillingCountry, newAcc.BillingCountry));
            }
        }

        // If no billing countries changed in this batch, exit early
        if (updatedAccountsMap.isEmpty()) {
            return;
        }

        // Step 2: Query only the contacts belonging to the affected accounts.
        // This is extremely selective and completely avoids the 50,000 row query limit.
        List<Contact> contactsToUpdate = new List<Contact>();

        List<Contact> relatedContacts = [
            SELECT Id, AccountId, MailingCountry 
            FROM Contact 
            WHERE AccountId IN :updatedAccountsMap.keySet()
        ];

        // Step 3: Process only the relevant contacts based on the criteria
        for (Contact con : relatedContacts) {
            BillingCountryChange change = updatedAccountsMap.get(con.AccountId);

            if (change != null) {
                String oldBillingCountry = change.oldCountry;
                String newBillingCountry = change.newCountry;

                // Condition: Update contact if its MailingCountry is blank OR equal to the account's previous BillingCountry
                if (String.isBlank(con.MailingCountry) || 
                    (oldBillingCountry != null && con.MailingCountry.equalsIgnoreCase(oldBillingCountry))) {

                    con.MailingCountry = newBillingCountry;
                    contactsToUpdate.add(con);
                }
            }
        }

        // Step 4: Perform DML bulk update
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    // Helper class to store transition states of BillingCountry
    private class BillingCountryChange {
        public String oldCountry;
        public String newCountry;

        public BillingCountryChange(String oldCountry, String newCountry) {
            this.oldCountry = oldCountry;
            this.newCountry = newCountry;
        }
    }
}
