import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track contacts = [];
    @track errorMsg = '';

    searchTerm = '';
    delayTimeout;
    requestCounter = 0;
    lastResolvedRequest = 0;

    handleSearchChange(event) {
        this.searchTerm = event.target.value;

        // Clear any active pending timeout
        if (this.delayTimeout) {
            clearTimeout(this.delayTimeout);
        }

        const trimmedTerm = this.searchTerm ? this.searchTerm.trim() : '';

        // If less than 2 characters, clear results, clear errors, and cancel pending search
        if (trimmedTerm.length < 2) {
            this.contacts = [];
            this.errorMsg = '';
            return;
        }

        // Debounce search input for 300ms
        this.delayTimeout = setTimeout(() => {
            this.executeSearch(trimmedTerm);
        }, 300);
    }

    executeSearch(searchTerm) {
        // Increment request counter to track the sequence of the request
        this.requestCounter += 1;
        const currentRequestId = this.requestCounter;

        searchContacts({ searchTerm })
            .then((result) => {
                // Only process the response if it corresponds to the most recent request
                if (currentRequestId > this.lastResolvedRequest) {
                    this.lastResolvedRequest = currentRequestId;
                    this.contacts = result;
                    this.errorMsg = '';
                }
            })
            .catch((error) => {
                if (currentRequestId > this.lastResolvedRequest) {
                    this.lastResolvedRequest = currentRequestId;
                    this.contacts = [];
                    this.errorMsg = error?.body?.message || 'An error occurred while searching.';
                }
            });
    }

    disconnectedCallback() {
        // Prevent pending search from executing if component is unmounted
        if (this.delayTimeout) {
            clearTimeout(this.delayTimeout);
        }
    }
}
