import { LightningElement, api, track } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    @track opportunities = [];
    @track error = null;
    @track isLoading = false;

    connectedCallback() {
        this.fetchOpportunities();
    }

    fetchOpportunities() {
        if (!this.recordId) {
            return;
        }

        this.isLoading = true;
        this.error = null;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.error = null;
            })
            .catch((err) => {
                this.error = err;
                this.opportunities = [];
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    handleRetry() {
        this.fetchOpportunities();
    }

    get hasOpportunities() {
        return this.opportunities && this.opportunities.length > 0;
    }

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return 'An unknown error occurred.';
    }
}
