import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';

const ACTIONS = [
    { label: 'View', name: 'view' },
    { label: 'Edit', name: 'edit' },
    { label: 'Delete', name: 'delete' }
];

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Stage', fieldName: 'StageName', type: 'text' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: { rowActions: ACTIONS }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];
    @track localOpportunities = [];
    columns = COLUMNS;

    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = value || [];
        this.localOpportunities = [...this._opportunities];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDeleteRecord(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: recordId,
                actionName: actionName
            }
        });
    }

    async confirmAndDeleteRecord(row) {
        const result = await LightningConfirm.open({
            message: `Are you sure you want to delete the opportunity "${row.Name}"?`,
            variant: 'headerless',
            label: 'Delete Opportunity'
        });

        if (result) {
            try {
                await deleteRecord(row.Id);
                this.localOpportunities = this.localOpportunities.filter(opp => opp.Id !== row.Id);
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Opportunity deleted',
                        variant: 'success'
                    })
                );
            } catch (error) {
                let errorMessage = 'An unknown error occurred.';
                if (error && error.body && typeof error.body.message === 'string') {
                    errorMessage = error.body.message;
                }
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Delete failed',
                        message: errorMessage,
                        variant: 'error'
                    })
                );
            }
        }
    }
}
