import { LightningElement, api, track } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    @track hasError = false;

    handleReset() {
        this.hasError = false;
        const editors = this.template.querySelectorAll('c-line-item-editor');
        if (editors) {
            editors.forEach(editor => editor.reset());
        }
    }

    handleSubmit() {
        const editors = Array.from(this.template.querySelectorAll('c-line-item-editor'));
        let allValid = true;

        // Validate all editors to ensure all error messages are shown simultaneously
        editors.forEach(editor => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.hasError = false;
            const values = editors.map(editor => editor.getValue());
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: values }
            }));
        } else {
            this.hasError = true;
        }
    }
}
