import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting = null;
    @track longestWaitMinutes = null;
    @track errorMessage = null;

    intervalId = null;
    isLoading = false;

    connectedCallback() {
        // Initial fetch
        this.fetchStats();

        // Start polling every 60 seconds
        this.startPolling();

        // Handle visibility changes
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    async fetchStats() {
        // Prevent concurrent requests
        if (this.isLoading) {
            return;
        }

        // Do not fetch if the page is currently hidden
        if (document.visibilityState === 'hidden') {
            return;
        }

        this.isLoading = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.errorMessage = null;
        } catch (error) {
            let message = 'Unknown error';
            if (error && error.body && error.body.message) {
                message = error.body.message;
            } else if (error && error.message) {
                message = error.message;
            }
            this.errorMessage = message;
        } finally {
            this.isLoading = false;
        }
    }

    startPolling() {
        this.stopPolling();
        this.intervalId = setInterval(() => {
            this.fetchStats();
        }, 60000);
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Fetch immediately upon becoming visible and restart the polling cycle
            this.fetchStats();
            this.startPolling();
        } else {
            // Pause polling while hidden
            this.stopPolling();
        }
    };
}
