import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import registerAttendee from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFieldChange(event) {
        const fieldName = event.target.dataset.field;
        if (fieldName === 'fullName') {
            this.fullName = event.detail.value;
        } else if (fieldName === 'email') {
            this.email = event.detail.value;
        } else if (fieldName === 'company') {
            this.company = event.detail.value;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        const inputs = this.template.querySelectorAll('lightning-input');

        if (emailInput) {
            const emailValue = (this.email || '').trim().toLowerCase();
            const domain = emailValue.split('@')[1];
            const personalDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

            if (personalDomains.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let allValid = true;
        inputs.forEach(input => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        registerAttendee({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
        .then(() => {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
            this.fullName = '';
            this.email = '';
            this.company = '';
        })
        .catch(error => {
            let message = 'Unknown error';
            if (error && error.body && typeof error.body.message === 'string') {
                message = error.body.message;
            }
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: message,
                    variant: 'error'
                })
            );
        });
    }
}
