    }

    handleAdd() {
        const trimmedLabel = this.newLabel ? this.newLabel.trim() : '';
        if (!trimmedLabel) {
            return;
        }

        // Add new task to items
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label: trimmedLabel, done: false }
        ];

        // Clear the input
        this.newLabel = '';

        // Dispatch taskadded event with detail containing the trimmed label
        this.dispatchEvent(new CustomEvent('taskadded', { 
            detail: { label: trimmedLabel } 
        }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map(task => {
            if (task.id == id) {
                return { ...task, done: event.target.checked };
            }
            return task;
        });
    }
}
