public with sharing class EmployerService {
    /**
     * Sets the current employer for the specified contacts.
     * Updates the Contact's primary affiliation field. NPSP automatically manages
     * the creation of new Affiliation records, marking them as Primary and Current,
     * and marking older primary affiliations as Former with an end date of today.
     *
     * @param employerByContactId Map where key is Contact Id and value is Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // 1. Query the target contacts to check their existing Primary Affiliation (1 SOQL query)
        Map<Id, Contact> contactsToUpdate = new Map<Id, Contact>();
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c 
            FROM Contact 
            WHERE Id IN :employerByContactId.keySet()
        ];

        for (Contact c : contacts) {
            Id newEmployerId = employerByContactId.get(c.Id);
            // If the current primary affiliation is already set to the target organization, do nothing
            if (c.npsp__Primary_Affiliation__c != newEmployerId) {
                c.npsp__Primary_Affiliation__c = newEmployerId;
                contactsToUpdate.put(c.Id, c);
            }
        }

        // 2. Perform the update if there are changes (1 DML statement)
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate.values();
        }
    }
