public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Imports a list of WebGifts using the NPSP Data Importer API.
     * Processes them synchronously in the current transaction using the org's current Data Import Settings.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Create and insert NPSP Data Import staging records
        List<npsp__DataImport__c> diRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            diRecords.add(di);
        }

        // Insert staging records to generate IDs for processing
        insert diRecords;

        // 2. Fetch the active NPSP Data Import Settings
        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getOrgDefaults();

        // 3. Process the staging records synchronously using the NPSP API
        npsp.BDI_DataImporter.processDataImportRecords(diSettings, diRecords, false);

        // 4. Query the updated staging records to read the import outcomes
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id, 
                   npsp__Status__c, 
                   npsp__Contact1Imported__c, 
                   npsp__DonationImported__c, 
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :diRecords
        ]);

        // 5. Build and return the ImportResult list in the original input order
        for (npsp__DataImport__c originalDi : diRecords) {
            npsp__DataImport__c processed = processedMap.get(originalDi.Id);
            ImportResult res = new ImportResult();

            if (processed != null) {
                res.success = (processed.npsp__Status__c == 'Imported');
                res.contactId = processed.npsp__Contact1Imported__c;
                res.opportunityId = processed.npsp__DonationImported__c;
                res.errorMessage = processed.npsp__FailureInformation__c;
            } else {
                res.success = false;
                res.errorMessage = 'Staging record was not processed.';
            }
            results.add(res);
        }

        return results;
    }
}
