public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The list of household members cannot be null or empty.');
        }

        // Retrieve the 'HH_Account' Record Type Id for Account
        Id householdRecordTypeId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        // NPSP automatically creates a Household Account when a Contact is inserted with no AccountId.
        // However, inserting multiple contacts with no AccountId individually or in a list 
        // would normally result in NPSP creating multiple separate Household Accounts.
        // To ensure all members belong to ONE new NPSP Household Account:
        // 1. Insert the first contact (the primary contact) alone with no AccountId.
        //    NPSP will automatically create one Household Account for this contact.
        Contact primaryContact = members[0];
        insert primaryContact;

        // 2. Query the automatically created Household Account's Id from the inserted primary contact
        Contact insertedPrimary = [
            SELECT AccountId 
            FROM Contact 
            WHERE Id = :primaryContact.Id 
            LIMIT 1
        ];
        Id householdAccountId = insertedPrimary.AccountId;

        // 3. For any subsequent contacts, associate them with this newly created Household Account
        //    before inserting them, so that NPSP does not spawn extra accounts.
        if (members.size() > 1) {
            List<Contact> remainingMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdAccountId;
                remainingMembers.add(member);
            }
            insert remainingMembers;
        }

        // 4. Update the Household Account's primary contact field (npe01__One2OneContact__c)
        //    and ensure it uses the Household Account Record Type (in case of default fallbacks).
        Account householdAccount = new Account(
            Id = householdAccountId,
            RecordTypeId = householdRecordTypeId,
            npe01__One2OneContact__c = primaryContact.Id
        );
        update householdAccount;

        return householdAccountId;
    }
}
