                    ContactId = member.Id,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!contactRoles.isEmpty()) {
            insert contactRoles;
        }

        // Manually create the single payment as requested, ensuring no duplicates and correct parameters
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
