global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        List<Task> tasksToInsert = new List<Task>();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject sobj : oldlist) {
                Opportunity oldOpp = (Opportunity) sobj;
                oldMap.put(oldOpp.Id, oldOpp);
            }
        }

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                if (opp.IsWon && opp.IsClosed && opp.Amount >= 5000) {
                    tasksToInsert.add(createFollowUpTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                Opportunity oldOpp = oldMap.get(opp.Id);

                Boolean isNowQualified = (opp.IsWon && opp.IsClosed && opp.Amount >= 5000);
                Boolean wasPreviouslyQualified = (oldOpp != null && oldOpp.IsWon && oldOpp.IsClosed && oldOpp.Amount >= 5000);

                if (isNowQualified && !wasPreviouslyQualified) {
                    tasksToInsert.add(createFollowUpTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToInsert);
        }

        return dmlWrapper;
    }

    private Task createFollowUpTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.OwnerId = opp.OwnerId;

        // npsp__Primary_Contact__c is on the Opportunity object in NPSP
        t.WhoId = (Id) opp.get('npsp__Primary_Contact__c');

        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }

        return t;
    }
}
