        }
        if (Schema.sObjectType.FB_Employee__c.fields.Personal_Email__c.isAccessible()) {
            queryFields.add('Personal_Email__c');
        }

        // 3. Construct and Execute the Query securely
        String queryStr = 'SELECT ' + String.join(queryFields, ', ') + ' FROM FB_Employee__c ORDER BY Name ASC';

