public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // 1. Query Contacts belonging to the target Accounts
        List<Contact> contactsToUpdate = [
            SELECT Id, OwnerId 
            FROM Contact 
            WHERE AccountId IN :accountIds
        ];

        // 2. Prepare Account updates
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(Id = accId, OwnerId = newOwnerId));
        }

        // 3. Prepare Contact updates
        for (Contact c : contactsToUpdate) {
            c.OwnerId = newOwnerId;
        }

        // 4. Bypass Account triggers in TAF
        TriggerBase.bypass(Account.SObjectType);

        try {
            // Update Accounts and Contacts using standard all-or-none DML
            update accountsToUpdate;
            update contactsToUpdate;
        } finally {
            // 5. Ensure the bypass on Account is cleared, successfully or not
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
