@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    static void testAmountDecreaseScenarios() {
        // Generate fake Ids using TAF's utility class
        Id oppId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId4 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // Scenario 1: Reduction of more than half (1000 to 499) -> rejected
        Opportunity oldOpp1 = new Opportunity(Id = oppId1, Amount = 1000.00);
        Opportunity newOpp1 = new Opportunity(Id = oppId1, Amount = 499.00);

        // Scenario 2: Reduction of exactly half (1000 to 500) -> accepted
        Opportunity oldOpp2 = new Opportunity(Id = oppId2, Amount = 1000.00);
        Opportunity newOpp2 = new Opportunity(Id = oppId2, Amount = 500.00);

        // Scenario 3: Increase (1000 to 1200) -> accepted
        Opportunity oldOpp3 = new Opportunity(Id = oppId3, Amount = 1000.00);
        Opportunity newOpp3 = new Opportunity(Id = oppId3, Amount = 1200.00);

        // Scenario 4: Previous amount was null (null to 500) -> accepted
        Opportunity oldOpp4 = new Opportunity(Id = oppId4, Amount = null);
        Opportunity newOpp4 = new Opportunity(Id = oppId4, Amount = 500.00);

        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp1, oldOpp2, oldOpp3, oldOpp4 };
        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp1, newOpp2, newOpp3, newOpp4 };

        Test.startTest();
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        // Assert Scenario 1 (rejected)
        System.assert(newOpp1.hasErrors(), 'Opportunity 1 should have an error.');
        System.assertEquals(1, newOpp1.getErrors().size(), 'Opportunity 1 should have exactly one error.');
        System.assertEquals(TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE, newOpp1.getErrors()[0].getMessage(), 'Incorrect error message on Opportunity 1.');

        // Assert Scenario 2 (accepted)
        System.assert(!newOpp2.hasErrors(), 'Opportunity 2 should not have errors.');

        // Assert Scenario 3 (accepted)
        System.assert(!newOpp3.hasErrors(), 'Opportunity 3 should not have errors.');

        // Assert Scenario 4 (accepted)
        System.assert(!newOpp4.hasErrors(), 'Opportunity 4 should not have errors.');
    }

    @IsTest
    static void testMixedBulkRecords() {
        Id oppId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // Mixed records: some break the rule, others do not
        Opportunity oldOpp1 = new Opportunity(Id = oppId1, Amount = 100.00);
        Opportunity newOpp1 = new Opportunity(Id = oppId1, Amount = 40.00); // More than half reduction -> rejected

        Opportunity oldOpp2 = new Opportunity(Id = oppId2, Amount = 100.00);
        Opportunity newOpp2 = new Opportunity(Id = oppId2, Amount = 60.00); // Less than half reduction -> accepted

        Opportunity oldOpp3 = new Opportunity(Id = oppId3, Amount = 100.00);
        Opportunity newOpp3 = new Opportunity(Id = oppId3, Amount = 30.00); // More than half reduction -> rejected

        List<Opportunity> triggerOld = new List<Opportunity>{ oldOpp1, oldOpp2, oldOpp3 };
        List<Opportunity> triggerNew = new List<Opportunity>{ newOpp1, newOpp2, newOpp3 };

        Test.startTest();
